from test_bufftap import test
for category in ('buffs','weapons','consumables'):
 for context in ('party','raid'):
  test('Use Solo always available '+category+' '+context,"local B=BuffTap; B:Options(); B.contextControls."+category+".buttons."+context+".scripts.OnClick(); local g=B.contextControls."+category+"; assert(g.reset.enabled~=false and g.reset.shown); g.reset.scripts.OnClick(); assert(B:SituationValues('"+context+"','"+category+"')==nil); assert(g.reset.enabled~=false)")
for context in ('party','raid'):
 test('Checkbox updates context controls immediately '+context,"local B=BuffTap; B:Options(); B.contextControls.buffs.buttons."+context+".scripts.OnClick(); local g=B.contextControls.buffs; for _,row in ipairs(B.options.buffRows) do if row.def.key=='motw' then row.check:SetChecked(false); row.check.scripts.OnClick(row.check) end end; assert(g.reset.enabled~=false); assert(B:SituationValues('"+context+"','buffs').buffs.motw==false); g.reset.scripts.OnClick(); assert(not B:SituationValues('"+context+"','buffs')); assert(B:Enabled(B:FindBuff('motw')))")
test('Use Solo does not require Options rebuild after scalar edit',"local B=BuffTap; B:Options(); B.contextControls.buffs.buttons.party.scripts.OnClick(); local g=B.contextControls.buffs; local old=B.Options; B.Options=function() error('unexpected rebuild') end; B:SetSituationValue('party','buffs','seconds',90); assert(g.reset.enabled~=false and g.status.text:find('Applied automatically')); B.Options=old")
test('Use Solo still refuses combat mutation',"local B=BuffTap; B:Options(); B.contextControls.buffs.buttons.party.scripts.OnClick(); B:SetSituationValue('party','buffs','seconds',90); combat=true; B:UpdateContextControls(); assert(B.contextControls.buffs.reset.enabled==false); B.contextControls.buffs.reset.scripts.OnClick(); assert(B:SituationValues('party','buffs').seconds==90)")
test('Paladin target plans configurable with features off',"playerClass='PALADIN'; local B=BuffTap; B:InitDB(); B.db.friendlyTarget=false; B.db.nearbyEnabled=false; B.db.targetClassBlessings=true; B:Options(); for _,p in ipairs(B.options.targetBlessingPicks) do assert(not p.disabled) end")

test('Profile copy enables immediately after choosing source',"local B=BuffTap; B:CreateSettingsProfile('Copy source',true); B:CreateSettingsProfile('Copy destination',true); B:Options(); local p=B.options.profiles; assert(not p.copy.enabled); p.source.scripts.OnClick(p.source); local found=false; for _,row in ipairs(p.source.menu.rows) do if row.choice=='Copy source' then row.scripts.OnClick(row); found=true; break end end; assert(found and p.copy.enabled and p.sourceName=='Copy source')")
test('Profile delete enables immediately after choosing candidate',"local B=BuffTap; B:CreateSettingsProfile('Delete candidate',true); B:CreateSettingsProfile('Active profile',true); B:Options(); local p=B.options.profiles; assert(not p.delete.enabled); p.deletePick.scripts.OnClick(p.deletePick); local found=false; for _,row in ipairs(p.deletePick.menu.rows) do if row.choice=='Delete candidate' then row.scripts.OnClick(row); found=true; break end end; assert(found and p.delete.enabled and p.deleteName=='Delete candidate')")
